package com.nexus.property.wishlist;import com.nexus.property.auth.*;import com.nexus.property.core.*;import com.nexus.property.property.PropertyMapper;import jakarta.servlet.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/wishlist") public class WishlistController{private final Db db;public WishlistController(Db db){this.db=db;}private String wid(String uid){var w=db.one("SELECT id FROM wishlists WHERE customer_id=? ORDER BY created_at LIMIT 1",uid);if(w!=null)return Rows.s(w,"id");String id=db.uuid();long n=System.currentTimeMillis();db.exec("INSERT INTO wishlists(id,customer_id,name,created_at,updated_at) VALUES(?,?,?,?,?)",id,uid,"My Saved Properties",n,n);return id;}@GetMapping public Map<String,Object>get(HttpServletRequest r){var u=AuthFilter.role(r,"CUSTOMER","ADMIN");String w=wid(u.userId());var rows=db.all("SELECT p.*,u.full_name owner_name,u.email owner_email,u.phone owner_phone,(SELECT url FROM property_images WHERE property_id=p.id ORDER BY is_primary DESC,display_order LIMIT 1) primary_image,(SELECT AVG(score) FROM ratings WHERE property_id=p.id) avg_score,(SELECT COUNT(*) FROM ratings WHERE property_id=p.id) rating_count FROM wishlist_items wi JOIN properties p ON p.id=wi.property_id JOIN users u ON u.id=p.owner_id WHERE wi.wishlist_id=? ORDER BY wi.created_at DESC",w).stream().map(PropertyMapper::map).toList();return Api.ok("Wishlist retrieved successfully.",Map.of("id",w,"name","My Saved Properties","properties",rows));}@PostMapping("/toggle")public Map<String,Object>toggle(HttpServletRequest r,@RequestBody Map<String,Object>b){var u=AuthFilter.role(r,"CUSTOMER","ADMIN");String w=wid(u.userId()),pid=Objects.toString(b.get("propertyId"),"");var ex=db.one("SELECT id FROM wishlist_items WHERE wishlist_id=? AND property_id=?",w,pid);boolean saved;if(ex==null){db.exec("INSERT INTO wishlist_items(id,wishlist_id,property_id,created_at) VALUES(?,?,?,?)",db.uuid(),w,pid,System.currentTimeMillis());saved=true;}else{db.exec("DELETE FROM wishlist_items WHERE id=?",Rows.s(ex,"id"));saved=false;}return Api.ok(saved?"Property saved to your favorites.":"Property removed from your favorites.",Map.of("saved",saved,"propertyId",pid));}@GetMapping("/dashboard")public Map<String,Object>dash(HttpServletRequest r){var u=AuthFilter.role(r,"CUSTOMER","ADMIN");String w=wid(u.userId());return Api.ok("Dashboard summary retrieved.",Map.of("savedProperties",db.scalarLong("SELECT COUNT(*) FROM wishlist_items WHERE wishlist_id=?",w),"appointments",db.scalarLong("SELECT COUNT(*) FROM appointments WHERE customer_id=?",u.userId()),"inquiries",db.scalarLong("SELECT COUNT(*) FROM inquiries WHERE customer_id=?",u.userId()),"complaints",db.scalarLong("SELECT COUNT(*) FROM complaints WHERE customer_id=?",u.userId())));}}
